  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00075",
          "explanation": "Doctor changes urgency and plan after new leg-ultrasound result surfaces, shifting from routine clarification to immediate on-site escalation and targeted questioning.",
          "quote": "现在最该当面再问现场医生一句：‘这次下肢超声只写左小腿肌间静脉血流瘀滞，是否看到明确深静脉血栓？主干深静脉（股静脉、腘静脉）有没有看清？心超还需不需要继续催做来评估右心负担？’"
        },
        {
          "event_id": "lite_evt_00119",
          "explanation": "Family confirms the changed urgency and reprioritized action plan.",
          "quote": "医生您看现在这种情况继续等检查还可以吗？我现在最应该催现场医生问哪一句，怕我问不到重点。"
        }
      ],
      "completion": "complete",
      "explanation": "The family reported a new leg-ultrasound result indicating left calf muscle vein stasis, creating new information about a potential thrombotic source. The doctor explicitly changed the plan from waiting to urgent clarification, explained the reason, and redirected the caregiver to immediate bedside escalation questions. All HO1 criteria were met.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00208",
          "explanation": "Doctor provides a concise, case-specific ask list for the nurse/doctor, distinguishing between roles.",
          "quote": "你接下来不用反复追着问很多专业词，抓住一句就行：‘我们会继续观察红旗症状，也按医嘱继续抗凝。请问心超结果一出来，麻烦及时告诉我们有没有右心负担或病情升级证据。’"
        },
        {
          "event_id": "lite_evt_00292",
          "explanation": "Doctor creates a realistic bedside communication script with specific questions for medication, timing, and fallback if no one is available.",
          "quote": "你到时可以直接这样问主管医生：‘麻烦在出院小结里写清楚：这次到底是按疑似肺栓塞继续抗凝出院，还是以肺部感染恢复为主随访…’"
        }
      ],
      "completion": "complete",
      "explanation": "When the family was moving between windows, receiving inconsistent terms, and fatigued, the doctor created a prioritized question list for the nurse and observation doctor, assigned roles, and included a fallback strategy. HO2 completion is evidenced by the script integrating PE suspicion, anticoagulation, and pending tests into a feasible bedside communication plan.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00065",
          "explanation": "Doctor uses workspace query to identify the mismatch between the family's uncertainty about test execution and the record showing an ultrasound was ordered but not resulted.",
          "quote": "候候选服务事件：心超和下肢血管超声可能因急诊资源与优先级暂时未排到，需现场医生评估是否升级急查。"
        },
        {
          "event_id": "lite_evt_00075",
          "explanation": "Doctor converts discovered mismatch into a targeted bedside verification task.",
          "quote": "你理解得对，‘大动脉没事’不能代表静脉没事。动脉和静脉不是一回事。肺栓塞通常更相关的是静脉血栓，所以这句‘大动脉未见明显异常’对判断肺栓塞帮助有限。"
        }
      ],
      "completion": "complete",
      "explanation": "The family stated uncertainty about whether leg ultrasound and echo were actually ordered or completed. The doctor used workspace query to surface the staged order and then integrated that mismatch into a targeted plan for bedside clarification. HO3 was completed with meaningful impact on the trajectory.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00075",
          "explanation": "Doctor corrects the family's misconception that muscle vein stasis equals confirmed deep vein thrombosis, linking correction to continued anticoagulation.",
          "quote": "它和你担心的‘大腿根部、腘窝后面那些主干深静脉明确血栓’不是同一个力度的结论。再加上报告还写了急诊超声信息有限、要结合临床，说明这个超声本身就不是一个能一锤定音的结果。"
        },
        {
          "event_id": "lite_evt_00164",
          "explanation": "Caregiver acknowledges the corrected understanding and confirms the behavioral consequence: not stopping anticoagulation.",
          "quote": "那我现在理解就是：我们别自己停抗凝针，先按现场医嘱继续抗凝抗感染，等心超，主要盯这些危险信号，对吗？"
        }
      ],
      "completion": "complete",
      "explanation": "The family surfaced a specific misconception that 'muscle vein stasis means confirmed thrombosis and more severe PE.' The doctor corrected this with case-specific facts and linked the correction to continued anticoagulation and monitoring. HO4 was fully completed with behavioral impact.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
